import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

// Physics lessons with videos
const PHYSICS_LESSONS = [
  {
    lesson_number: 1,
    title: "Motion & Forces",
    videos: [
      { id: 1, title: "What is Physics?", url: "https://www.youtube.com/embed/sJG-A7MwVzc" },
      { id: 2, title: "Newton's First Law", url: "https://www.youtube.com/embed/9f0ZtfTZMqE" },
      { id: 3, title: "Newton's Second Law", url: "https://www.youtube.com/embed/SlKa_nrqvgQ" },
      { id: 4, title: "Newton's Third Law", url: "https://www.youtube.com/embed/H8jZuqXlnSI" },
      { id: 5, title: "Vectors & Scalars", url: "https://www.youtube.com/embed/RyEKvLy0_5g" }
    ]
  },
  {
    lesson_number: 2,
    title: "Energy & Work",
    videos: [
      { id: 1, title: "What is Work?", url: "https://www.youtube.com/embed/kHFcXbhqIQY" },
      { id: 2, title: "Kinetic Energy", url: "https://www.youtube.com/embed/f7LaGd_VBe0" },
      { id: 3, title: "Potential Energy", url: "https://www.youtube.com/embed/6gCWDkE_KYY" },
      { id: 4, title: "Conservation of Energy", url: "https://www.youtube.com/embed/RlhIR2WddVg" },
      { id: 5, title: "Power", url: "https://www.youtube.com/embed/eJ7r8Ps3fO8" }
    ]
  },
  {
    lesson_number: 3,
    title: "Waves & Sound",
    videos: [
      { id: 1, title: "What is a Wave?", url: "https://www.youtube.com/embed/E-T-2jWHfqU" },
      { id: 2, title: "Wave Properties", url: "https://www.youtube.com/embed/Qp7PYXhJBQg" },
      { id: 3, title: "Sound Waves", url: "https://www.youtube.com/embed/ztkBc3q25P4" },
      { id: 4, title: "Doppler Effect", url: "https://www.youtube.com/embed/h4OnBYrbCjY" },
      { id: 5, title: "Resonance", url: "https://www.youtube.com/embed/xr82Dg7YzQk" }
    ]
  },
  {
    lesson_number: 4,
    title: "Light & Optics",
    videos: [
      { id: 1, title: "Properties of Light", url: "https://www.youtube.com/embed/XGDMgnpCJtI" },
      { id: 2, title: "Reflection", url: "https://www.youtube.com/embed/bUXDjqVL4fA" },
      { id: 3, title: "Refraction", url: "https://www.youtube.com/embed/7JULqC5Lfow" },
      { id: 4, title: "Lenses", url: "https://www.youtube.com/embed/j3pKrr4-nTg" },
      { id: 5, title: "Electromagnetic Spectrum", url: "https://www.youtube.com/embed/Ct8e4dZXcfo" }
    ]
  },
  {
    lesson_number: 5,
    title: "Electricity & Magnetism",
    videos: [
      { id: 1, title: "Electric Charge", url: "https://www.youtube.com/embed/RqoKm3qr--Q" },
      { id: 2, title: "Electric Force & Field", url: "https://www.youtube.com/embed/2nYF2Ov18MI" },
      { id: 3, title: "Electric Current", url: "https://www.youtube.com/embed/cNbYUEsWAcY" },
      { id: 4, title: "Magnetism", url: "https://www.youtube.com/embed/0xrZgZ2K6FY" },
      { id: 5, title: "Electromagnetism", url: "https://www.youtube.com/embed/Ps49QLAH6yA" }
    ]
  },
  {
    lesson_number: 6,
    title: "Circuits & Electronics",
    videos: [
      { id: 1, title: "Ohm's Law", url: "https://www.youtube.com/embed/uRMm2nXUWVo" },
      { id: 2, title: "Series & Parallel Circuits", url: "https://www.youtube.com/embed/vRBp31zBT4I" },
      { id: 3, title: "Power & Resistance", url: "https://www.youtube.com/embed/6FzSWv9xzHc" },
      { id: 4, title: "Capacitors", url: "https://www.youtube.com/embed/8_pMSMkEfK4" },
      { id: 5, title: "Semiconductors", url: "https://www.youtube.com/embed/2h3uPiBwKs8" }
    ]
  },
  {
    lesson_number: 7,
    title: "Thermal Physics",
    videos: [
      { id: 1, title: "Temperature & Heat", url: "https://www.youtube.com/embed/X6Fg9FhXPPM" },
      { id: 2, title: "Laws of Thermodynamics", url: "https://www.youtube.com/embed/EhDKFGhgmM4" },
      { id: 3, title: "Specific Heat Capacity", url: "https://www.youtube.com/embed/xPGrRZ6G2nQ" },
      { id: 4, title: "Phase Changes", url: "https://www.youtube.com/embed/H4SqfpN_sJ0" },
      { id: 5, title: "Gas Laws", url: "https://www.youtube.com/embed/gShWe7-vAeU" }
    ]
  },
  {
    lesson_number: 8,
    title: "Modern Physics",
    videos: [
      { id: 1, title: "Quantum Mechanics", url: "https://www.youtube.com/embed/WGsHFg-yKAg" },
      { id: 2, title: "Photoelectric Effect", url: "https://www.youtube.com/embed/bSt9PrYj1Bg" },
      { id: 3, title: "Atoms & Nuclei", url: "https://www.youtube.com/embed/0P_7r4gfgOY" },
      { id: 4, title: "Radioactivity", url: "https://www.youtube.com/embed/ZALu3b9RhFY" },
      { id: 5, title: "Nuclear Energy", url: "https://www.youtube.com/embed/5w-5s6PBQNY" }
    ]
  },
  {
    lesson_number: 9,
    title: "Relativity",
    videos: [
      { id: 1, title: "Special Relativity", url: "https://www.youtube.com/embed/wteiWlNaKqI" },
      { id: 2, title: "Time Dilation", url: "https://www.youtube.com/embed/CrrT4eeVsVc" },
      { id: 3, title: "Mass-Energy Equivalence", url: "https://www.youtube.com/embed/w7ZS5FoXmGY" },
      { id: 4, title: "General Relativity", url: "https://www.youtube.com/embed/foRQaYknVjE" },
      { id: 5, title: "Black Holes", url: "https://www.youtube.com/embed/e-P5IFTqB98" }
    ]
  },
  {
    lesson_number: 10,
    title: "Applications & Future",
    videos: [
      { id: 1, title: "Renewable Energy", url: "https://www.youtube.com/embed/FVEIuqpFoKQ" },
      { id: 2, title: "Quantum Computing", url: "https://www.youtube.com/embed/JhHMJCUmzQY" },
      { id: 3, title: "Space Exploration", url: "https://www.youtube.com/embed/d7e0fPzV1VU" },
      { id: 4, title: "Medical Physics", url: "https://www.youtube.com/embed/iMRLaYVG9V8" },
      { id: 5, title: "Physics of the Future", url: "https://www.youtube.com/embed/pF1Mz4Z6Kc4" }
    ]
  }
];

export default function Physics() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    setSub("Physics");
    setLessons(PHYSICS_LESSONS);
    setLoading(false);
  }, []);

  if (loading) return <div>Loading...</div>;

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>{sub}</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
